import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO

# Load data
df = pd.read_csv('/app/benchmark/data.csv', encoding='utf-8-sig')

# Clean column names in case of BOM
df.columns = df.columns.str.replace('\ufeff', '')
df.columns = df.columns.str.strip()

# Check unique apps to ensure clean names
apps = df['App'].unique()

def get_base64_image(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight')
    buf.seek(0)
    img_str = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return img_str

# Set seaborn style
sns.set_theme(style="whitegrid")

# 1. Average Star Rating and Mean Sentiment Polarity by App
app_stats = df.groupby('App').agg({
    'Star_Rating': 'mean',
    'Sentiment_Polarity': 'mean',
    'Word_Count': 'mean',
    'Thumbs_Up_Count': 'mean'
}).reset_index()

# Plot Average Star Rating
fig, ax = plt.subplots(figsize=(8, 5))
sns.barplot(data=app_stats.sort_values('Star_Rating', ascending=False), x='App', y='Star_Rating', palette='viridis')
plt.title('Average Star Rating by App')
plt.ylim(1, 5)
for i, v in enumerate(app_stats.sort_values('Star_Rating', ascending=False)['Star_Rating']):
    ax.text(i, v + 0.05, f"{v:.2f}", ha='center')
img_star_rating = get_base64_image(fig)

# Plot Mean Sentiment Polarity
fig, ax = plt.subplots(figsize=(8, 5))
sns.barplot(data=app_stats.sort_values('Sentiment_Polarity', ascending=False), x='App', y='Sentiment_Polarity', palette='coolwarm')
plt.title('Mean Sentiment Polarity by App')
plt.ylim(-1, 1)
for i, v in enumerate(app_stats.sort_values('Sentiment_Polarity', ascending=False)['Sentiment_Polarity']):
    ax.text(i, v + 0.02, f"{v:.3f}", ha='center')
img_sentiment = get_base64_image(fig)

# 2. Complaint Theme Rate (Thematic Complaint Analysis)
theme_counts = df.groupby(['App', 'Review_Theme']).size().unstack(fill_value=0)
theme_percentages = theme_counts.div(theme_counts.sum(axis=1), axis=0) * 100

fig, ax = plt.subplots(figsize=(10, 6))
theme_percentages[['Bugs', 'Accuracy', 'Pricing', 'General']].plot(kind='bar', stacked=True, ax=ax, colormap='Set2')
plt.title('Review Theme Distribution by App (%)')
plt.ylabel('Percentage')
plt.legend(title='Theme', bbox_to_anchor=(1.05, 1), loc='upper left')
plt.xticks(rotation=0)
img_themes = get_base64_image(fig)

# Extract specific complaint stats for text
complaint_stats = theme_percentages[['Bugs', 'Accuracy', 'Pricing']].to_dict('index')

# 3. Sentiment-Rating Mismatch Rate
# Define mismatch: (Star >= 4 and Polarity < -0.2) OR (Star <= 2 and Polarity > 0.2)
# Or maybe: 5-star with negative polarity (< 0), 1-star with positive polarity (> 0)
df['Mismatch'] = (((df['Star_Rating'] >= 4) & (df['Sentiment_Polarity'] <= -0.1)) | 
                  ((df['Star_Rating'] <= 2) & (df['Sentiment_Polarity'] >= 0.1)))

mismatch_rate = df.groupby('App')['Mismatch'].mean() * 100

fig, ax = plt.subplots(figsize=(8, 5))
sns.barplot(x=mismatch_rate.index, y=mismatch_rate.values, palette='magma')
plt.title('Sentiment-Rating Mismatch Rate (%)')
plt.ylabel('Mismatch Rate (%)')
for i, v in enumerate(mismatch_rate.values):
    ax.text(i, v + 0.2, f"{v:.1f}%", ha='center')
img_mismatch = get_base64_image(fig)

# 4. Review Depth & Emotional Intensity
# Correlation between word count and rating
# Correlation between word count and sentiment
# Group by star rating and calculate average word count
word_count_by_rating = df.groupby('Star_Rating')['Word_Count'].mean().reset_index()

fig, ax = plt.subplots(figsize=(8, 5))
sns.lineplot(data=word_count_by_rating, x='Star_Rating', y='Word_Count', marker='o', linewidth=2)
plt.title('Average Word Count by Star Rating')
plt.xticks([1, 2, 3, 4, 5])
plt.ylabel('Avg Word Count')
img_depth = get_base64_image(fig)

# 5. Average Review Engagement (Thumbs Up)
engagement_by_theme = df.groupby('Review_Theme')['Thumbs_Up_Count'].mean().reset_index()
fig, ax = plt.subplots(figsize=(8, 5))
sns.barplot(data=engagement_by_theme.sort_values('Thumbs_Up_Count', ascending=False), x='Review_Theme', y='Thumbs_Up_Count', palette='pastel')
plt.title('Average Thumbs Up Count by Theme')
plt.ylabel('Avg Thumbs Up Count')
img_engagement = get_base64_image(fig)


