    acc = complaint_stats[app].get('Accuracy', 0)
    price = complaint_stats[app].get('Pricing', 0)
    theme_table_rows += f"<tr><td>{app}</td><td>{bugs:.1f}%</td><td>{acc:.1f}%</td><td>{price:.1f}%</td></tr>\n"


final_html = html_template.format(
