    theme_table_rows=theme_table_rows,
    img_mismatch=img_mismatch,
    img_depth=img_depth,
    img_engagement=img_engagement
)

with open('/app/output/final_report.html', 'w', encoding='utf-8') as f:
    f.write(final_html)

print("Report generated successfully.")

